28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be valid E.164")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date", columnDefinition = "DATE")
56	    private java.time.LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    public String getCustomerCode() {
68	        return this.customerCode;
69	    }
70	
71	    public Integer getNamesakeCount() {
72	        return this.namesakeCount;
73	    }
74	
75	    public void setNamesakeCount(Integer namesakeCount) {
76	        this.namesakeCount = namesakeCount;
77	    }
78	
79	    /** Record how many of {@code existingOwners} share this owner's first and last name, case-insensitively. */
80	    public void assignNamesakeCount(Collection<Owner> existingOwners) {
81	        int count = 0;
82	        for (Owner other : existingOwners) {
83	            if (getFirstName().equalsIgnoreCase(other.getFirstName())
84	                && getLastName().equalsIgnoreCase(other.getLastName())) {
85	                count++;
86	            }
87	        }
88	        this.namesakeCount = count;
89	    }
90	
91	    public String getHouseholdId() {
92	        return this.householdId;
93	    }
94	
95	    public void setHouseholdId(String householdId) {
96	        this.householdId = householdId;
97	    }
98	
99	    /** Assign the '<CITY3>-<LAST3>-<NNNN>' customer code, where NNNN is one more than {@code cityCount}. */
100	    public void assignCustomerCode(int cityCount) {
101	        String city3 = getCity().substring(0, Math.min(3, getCity().length())).toUpperCase(Locale.ROOT);
102	        String last3 = getLastName().substring(0, Math.min(3, getLastName().length())).toUpperCase(Locale.ROOT);
103	        this.customerCode = String.format("%s-%s-%04d", city3, last3, cityCount + 1);
104	    }
105	
106	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
107	    private Set<Pet> pets;
108	
109	    public java.time.LocalDate getRegistrationDate() {
110	        return this.registrationDate;
111	    }
112	
113	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
114	        this.registrationDate = registrationDate;
115	    }
116	
117	    public String getAddress() {
118	        return this.address;
119	    }
120	
121	    /** Store the address normalized so create persists and returns the canonical form. */
122	    public void setAddress(String address) {
123	        this.address = AddressNormalizer.normalize(address);
124	    }
125	
126	    public String getCity() {
127	        return this.city;
128	    }
129	
130	    public void setCity(String city) {
131	        this.city = city;
132	    }
133	
134	    public String getTelephone() {
135	        return this.telephone;
136	    }
137	
138	    /** Store the telephone in E.164 form so create and update persist and return it normalized. */
139	    public void setTelephone(String telephone) {
140	        this.telephone = TelephoneNormalizer.toE164(telephone);
141	    }
142	
143	    public String getEmail() {
144	        return this.email;
145	    }
146	
147	    /** Store the address lower-cased so it is persisted and returned normalized. */
148	    public void setEmail(String email) {
149	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
150	    }
151	
152	    protected Set<Pet> getPetsInternal() {
153	        if (this.pets == null) {
154	            this.pets = new HashSet<>();
155	        }
156	        return this.pets;
157	    }
158	
159	    protected void setPetsInternal(Set<Pet> pets) {
160	        this.pets = pets;
161	    }
162	
163	    public List<Pet> getPets() {
164	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
165	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
166	        return Collections.unmodifiableList(sortedPets);
167	    }
168	
169	    public void setPets(List<Pet> pets) {
170	        this.pets = new HashSet<>(pets);
171	    }
172	
173	    public void addPet(Pet pet) {
174	        getPetsInternal().add(pet);
175	        pet.setOwner(this);
176	    }
177	
178	    /**
179	     * Return the Pet with the given name, or null if none found for this Owner.
180	     *
181	     * @param name to test
182	     * @return true if pet name is already in use
183	     */
184	    public Pet getPet(String name) {
185	        return getPet(name, false);
186	    }
187	
188	    /**
189	     * Return the Pet with the given name, or null if none found for this Owner.
190	     *
191	     * @param name to test
192	     * @return true if pet name is already in use
193	     */
194	    public Pet getPet(String name, boolean ignoreNew) {
195	        name = name.toLowerCase();
196	        for (Pet pet : getPetsInternal()) {
197	            if (!ignoreNew || !pet.isNew()) {
198	                String compName = pet.getName();
199	                compName = compName.toLowerCase();
200	                if (compName.equals(name)) {
201	                    return pet;
202	                }
203	            }
204	        }
205	        return null;
206	    }
207	
208	    public Pet getPet(Integer petId) {
209	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
210	    }
211	
212	    @Override
213	    public String toString() {
214	        return new ToStringCreator(this)
215	
216	            .append("id", this.getId())
217	            .append("new", this.isNew())
218	            .append("lastName", this.getLastName())
219	            .append("firstName", this.getFirstName())
220	            .append("address", this.address)
221	            .append("city", this.city)
222	            .append("telephone", this.telephone)
223	            .toString();
224	    }
225	}
