97	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
98	    }
99	
100	    private boolean isHouseholdTaken(String lastName, String address) {
101	        String key = normalize(lastName) + '\n' + AddressNormalizer.normalize(address);
102	        for (Owner existing : clinicService.findAllOwners()) {
103	            if (key.equals(normalize(existing.getLastName()) + '\n' + AddressNormalizer.normalize(existing.getAddress()))) {
104	                return true;
105	            }
106	        }
107	        return false;
108	    }
109	
110	    private String normalize(String value) {
111	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
112	    }
113	
114	    private HttpInputMessage buffered(byte[] bytes, HttpHeaders headers) {
115	        return new HttpInputMessage() {
116	            @Override
117	            public InputStream getBody() {
118	                return new ByteArrayInputStream(bytes);
119	            }
120	
121	            @Override
122	            public HttpHeaders getHeaders() {
123	                return headers;
124	            }
125	        };
126	    }
127	
128	    @Override
129	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
130	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
131	        return body;
132	    }
133	
134	    @Override
135	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
136	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
137	        return body;
138	    }
