38	/**
39	 * Rejects a create-owner request whose normalized telephone (non-digit characters
40	 * stripped, matching how the create path stores it) is already used by an existing
41	 * owner, responding 409 Conflict. Applies only to the create endpoint so updates that
42	 * keep an owner's own telephone are unaffected.
43	 */
44	@ControllerAdvice
45	@Order(Ordered.HIGHEST_PRECEDENCE)
46	public class OwnerUniqueTelephoneAdvice implements RequestBodyAdvice {
47	
48	    private final ClinicService clinicService;
49	
50	    private final OwnerMapper ownerMapper;
51	
52	    public OwnerUniqueTelephoneAdvice(ClinicService clinicService, OwnerMapper ownerMapper) {
53	        this.clinicService = clinicService;
54	        this.ownerMapper = ownerMapper;
55	    }
56	
57	    @Override
58	    public boolean supports(MethodParameter methodParameter, Type targetType,
59	                            Class<? extends HttpMessageConverter<?>> converterType) {
60	        Method method = methodParameter.getMethod();
61	        return OwnerFieldsDto.class.equals(targetType) && method != null
62	            && "addOwner".equals(method.getName());
63	    }
64	
65	    @Override
66	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
67	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
68	        String telephone = ownerMapper.normalizeTelephone(((OwnerFieldsDto) body).getTelephone());
69	        if (telephone != null && isTelephoneTaken(telephone)) {
70	            throw new DuplicateTelephoneException();
71	        }
72	        return body;
73	    }
74	
75	    private boolean isTelephoneTaken(String telephone) {
76	        for (Owner existing : clinicService.findAllOwners()) {
77	            if (telephone.equals(ownerMapper.normalizeTelephone(existing.getTelephone()))) {
78	                return true;
79	            }
80	        }
81	        return false;
82	    }
