18	import java.time.DayOfWeek;
19	import java.time.LocalDate;
20	
21	/**
22	 * Rolls dates forward off the weekend onto a business day.
23	 */
24	public final class BusinessDays {
25	
26	    private BusinessDays() {
27	    }
28	
29	    /** Return {@code date} unchanged on a weekday, or the next Monday when it is a Saturday or Sunday. */
30	    public static LocalDate toBusinessDay(LocalDate date) {
31	        DayOfWeek day = date.getDayOfWeek();
32	        if (day == DayOfWeek.SATURDAY) {
33	            return date.plusDays(2);
34	        }
35	        if (day == DayOfWeek.SUNDAY) {
36	            return date.plusDays(1);
37	        }
38	        return date;
39	    }
40	}
